import { getSSOConfig } from '../config';
import { SSOConfig } from '../types';

export interface SSOUPProviderOptions {
  ssoUrl?: string;
  clientId?: string;
  clientSecret?: string;
  scope?: string;
  prompt?: 'login' | string | null;
}

/**
 * Pre-configured NextAuth.js / Auth.js OAuth Provider for SSO UP.
 * Compatible with NextAuth v4 and NextAuth v5 (Auth.js).
 *
 * Usage in `pages/api/auth/[...nextauth].ts` or `app/api/auth/[...nextauth]/route.ts`:
 * ```ts
 * import NextAuth from 'next-auth';
 * import { SSOUPProvider } from '@webkampus/sso-client-next/next-auth';
 *
 * export default NextAuth({
 *   providers: [
 *     SSOUPProvider({
 *       clientId: process.env.SSO_CLIENT_ID,
 *       clientSecret: process.env.SSO_CLIENT_SECRET,
 *     })
 *   ]
 * })
 * ```
 */
export function SSOUPProvider(options?: SSOUPProviderOptions) {
  const config = getSSOConfig(options);

  return {
    id: 'sso-up',
    name: 'SSO Universitas Pahlawan',
    type: 'oauth',
    version: '2.0',
    authorization: {
      url: `${config.ssoUrl}/oauth/authorize`,
      params: {
        scope: config.scope || '*',
        ...(config.prompt ? { prompt: config.prompt } : {}),
      },
    },
    token: `${config.ssoUrl}/oauth/token`,
    userinfo: `${config.ssoUrl}/api/userinfo`,
    clientId: config.clientId,
    clientSecret: config.clientSecret,
    profile(profile: any) {
      return {
        id: profile.sub || String(profile.id),
        name: profile.name,
        email: profile.email,
        username: profile.username,
        role: profile.role || 'user',
        image: profile.avatar || profile.profile?.avatar || profile.profile?.foto || null,
        sainsData: profile.profile || profile.sains_data || {},
      };
    },
  };
}
